arguments.command:
cd /testbed && printf '%s\n' '--- alias resolution ---' && nl -ba alias.go | sed -n '1,180p' && mkdir -p .repro && cat > .repro/main.go <<'EOF'
package main
import (
 "fmt"
 cast "github.com/spf13/cast"
)
func main() {
 var s *string
 v, err := cast.ToStringE(s)
 fmt.Printf("%q %v\n", v, err)
}
EOF
printf '%s\n' '--- reproduction (timeout protects shell) ---' && timeout 2s go run ./.repro/main.go; status=$?; rm -rf .repro; exit $status

